package com.github.havardpede.partylink;

import java.util.function.Consumer;
import lombok.extern.slf4j.Slf4j;

@Slf4j
class CommandExecutor {
	private final Consumer<String> changeParty;
	private final Consumer<String> sendChatMessage;

	private volatile Command pendingJoin;
	private volatile Runnable pendingAck;

	CommandExecutor(Consumer<String> changeParty, Consumer<String> sendChatMessage) {
		this.changeParty = changeParty;
		this.sendChatMessage = sendChatMessage;
	}

	void execute(Command command, Runnable ack) {
		if (command.type == null) {
			log.warn("Unknown command type (command={})", command.id);
			return;
		}

		switch (command.type) {
			case JOIN_PARTY:
				log.info("Queueing JOIN_PARTY (command={}, role={})", command.id, command.role);
				pendingJoin = command;
				pendingAck = ack;
				sendChatMessage.accept(buildInviteMessage(command.role));
				break;
			case LEAVE_PARTY:
				log.info(
						"Executing LEAVE_PARTY (command={}, reason={})",
						command.id,
						command.reason);
				clearPendingJoin();
				changeParty.accept(null);
				sendLeaveMessage(command.reason);
				ack.run();
				break;
			case ROLE_CHANGE:
				log.info("Executing ROLE_CHANGE (command={}, role={})", command.id, command.role);
				sendChatMessage.accept("Your role has been changed to " + command.role + ".");
				ack.run();
				break;
		}
	}

	boolean executePendingJoin() {
		Command cmd = pendingJoin;
		Runnable ack = pendingAck;
		if (cmd == null) {
			return false;
		}
		pendingJoin = null;
		pendingAck = null;
		log.info("Player accepted JOIN_PARTY (command={}, role={})", cmd.id, cmd.role);
		changeParty.accept(cmd.passphrase);
		sendChatMessage.accept(buildJoinedMessage(cmd.role));
		ack.run();
		return true;
	}

	private void clearPendingJoin() {
		Runnable ack = pendingAck;
		pendingJoin = null;
		pendingAck = null;
		if (ack != null) {
			ack.run();
		}
	}

	private static String buildInviteMessage(String role) {
		if (role != null) {
			return "You have been invited to join a party as "
					+ role
					+ ". Type ::join to accept.";
		}
		return "You have been invited to join a party. Type ::join to accept.";
	}

	private static String buildJoinedMessage(String role) {
		if (role != null) {
			return "You have joined the party. Your role is " + role + ".";
		}
		return "You have joined the party.";
	}

	private void sendLeaveMessage(LeaveReason reason) {
		if (reason == LeaveReason.KICKED) {
			sendChatMessage.accept("You have been kicked from the party.");
		} else if (reason == LeaveReason.CLOSED) {
			sendChatMessage.accept("The party has been closed by the leader.");
		}
	}
}

package com.github.havardpede.partylink;

import com.google.inject.Provides;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.CommandExecuted;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.PartyChanged;
import net.runelite.client.party.PartyService;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import okhttp3.OkHttpClient;

@Slf4j
@PluginDescriptor(
		name = "Party Link",
		description =
				"Connects RuneLite to an external server for remote party management. "
						+ "Pair with your server to sync parties and receive commands in real time.")
public class LinkPlugin extends Plugin {
	private static final String JOIN_COMMAND = "join";
	private static final String LEAVE_COMMAND = "leave";

	@Inject private Client client;
	@Inject private PartyService partyService;
	@Inject private OkHttpClient okHttpClient;
	@Inject private ScheduledExecutorService executorService;
	@Inject private ClientThread clientThread;
	@Inject private ChatMessageManager chatMessageManager;
	@Inject private ConfigManager configManager;
	@Inject private LinkConfig config;

	private WebSocketManager webSocketManager;
	private RsnDetector rsnDetector;
	private CommandExecutor commandExecutor;

	@Override
	protected void startUp() {
		String wsUrl = config.websocketUrl();
		if (wsUrl == null || wsUrl.isEmpty()) {
			log.warn("Link plugin not started: WebSocket URL is not configured");
			return;
		}

		OkHttpClient wsClient =
				okHttpClient.newBuilder().pingInterval(30, TimeUnit.SECONDS).build();
		commandExecutor = new CommandExecutor(this::changeParty, this::sendChatMessage);
		webSocketManager =
				new WebSocketManager(
						wsClient,
						wsUrl,
						this::getStoredToken,
						this::getPairingCode,
						this::onPairResult,
						commandExecutor,
						executorService);
		rsnDetector = new RsnDetector(webSocketManager::sendIdentify, this::getPlayerName);
		log.info(
				"Link plugin started: gameState={}, enabled={}, hasToken={}, hasPairingCode={}",
				client.getGameState(),
				config.enabled(),
				hasToken(),
				hasPairingCode());

		if (client.getGameState() == GameState.LOGGED_IN) {
			if (config.enabled() && (hasToken() || hasPairingCode())) {
				webSocketManager.connect();
			}
			rsnDetector.onLoggedIn();
		}
	}

	@Override
	protected void shutDown() {
		commandExecutor = null;
		if (webSocketManager != null) {
			webSocketManager.disconnect();
		}
		log.info("Link plugin stopped");
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		switch (event.getGameState()) {
			case LOGGED_IN:
				if (config.enabled() && (hasToken() || hasPairingCode())) {
					webSocketManager.connect();
				}
				rsnDetector.onLoggedIn();
				break;
			case LOGIN_SCREEN:
				webSocketManager.disconnect();
				break;
		}
	}

	@Subscribe
	public void onCommandExecuted(CommandExecuted event) {
		if (JOIN_COMMAND.equalsIgnoreCase(event.getCommand())) {
			onJoinCommand();
		} else if (LEAVE_COMMAND.equalsIgnoreCase(event.getCommand())) {
			changeParty(null);
		}
	}

	@Subscribe
	public void onGameTick(GameTick event) {
		rsnDetector.onGameTick();
	}

	@Subscribe
	public void onPartyChanged(PartyChanged event) {
		if (webSocketManager == null) {
			return;
		}
		String passphrase = event.getPassphrase();
		if (passphrase != null) {
			webSocketManager.sendPartyState("JOINED", passphrase);
		} else {
			webSocketManager.sendPartyState("LEFT", null);
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event) {
		if (!LinkConfig.CONFIG_GROUP.equals(event.getGroup())) {
			return;
		}
		switch (event.getKey()) {
			case "pairingKey":
				handlePairingKeyChange(event.getNewValue());
				break;
			case "enabled":
			case "websocketUrl":
				restart();
				break;
			case LinkConfig.BEARER_TOKEN_KEY:
				if (!hasToken() && webSocketManager != null) {
					webSocketManager.disconnect();
				}
				break;
		}
	}

	@Provides
	LinkConfig provideConfig(ConfigManager configManager) {
		return configManager.getConfig(LinkConfig.class);
	}

	private String getPlayerName() {
		return client.getLocalPlayer() != null ? client.getLocalPlayer().getName() : null;
	}

	private void onJoinCommand() {
		if (commandExecutor == null || !commandExecutor.executePendingJoin()) {
			sendChatMessage("No pending party invitation.");
		}
	}

	private void changeParty(String passphrase) {
		clientThread.invokeLater(() -> partyService.changeParty(passphrase));
	}

	private String getStoredToken() {
		String token =
				configManager.getConfiguration(
						LinkConfig.CONFIG_GROUP, LinkConfig.BEARER_TOKEN_KEY);
		return token != null ? token : "";
	}

	private boolean hasToken() {
		return !getStoredToken().isEmpty();
	}

	private String getPairingCode() {
		String code = config.pairingKey();
		return code != null ? code : "";
	}

	private boolean hasPairingCode() {
		return !getPairingCode().isEmpty();
	}

	private void restart() {
		shutDown();
		startUp();
	}

	private void handlePairingKeyChange(String pairingKey) {
		if (pairingKey == null || pairingKey.isEmpty()) {
			if (hasToken()) {
				return;
			}
			if (webSocketManager != null) {
				webSocketManager.disconnect();
			}
			sendChatMessage("Party Link: Unpaired.");
			return;
		}
		restart();
	}

	private void onPairResult(String token) {
		if (token != null) {
			configManager.setConfiguration(
					LinkConfig.CONFIG_GROUP, LinkConfig.BEARER_TOKEN_KEY, token);
		}
		configManager.unsetConfiguration(LinkConfig.CONFIG_GROUP, "pairingKey");
		if (token == null) {
			sendChatMessage("Party Link: Pairing failed. Check your code and try again.");
		} else {
			sendChatMessage("Party Link: Paired successfully!");
		}
	}

	private void sendChatMessage(String message) {
		chatMessageManager.queue(
				QueuedMessage.builder()
						.type(ChatMessageType.GAMEMESSAGE)
						.runeLiteFormattedMessage("<col=ff7700>" + message + "</col>")
						.build());
	}
}

package com.github.havardpede.partylink;

import com.google.gson.JsonObject;
import com.google.gson.JsonParser;

class Command {
	final String id;
	final CommandType type;
	final String passphrase;
	final LeaveReason reason;
	final String role;

	private Command(
			String id, CommandType type, String passphrase, LeaveReason reason, String role) {
		this.id = id;
		this.type = type;
		this.passphrase = passphrase;
		this.reason = reason;
		this.role = role;
	}

	static Command fromJson(String json) {
		JsonObject obj = new JsonParser().parse(json).getAsJsonObject();
		return new Command(
				obj.get("id").getAsString(),
				CommandType.fromString(obj.get("command").getAsString()),
				stringOrNull(obj, "passphrase"),
				LeaveReason.fromString(stringOrNull(obj, "reason")),
				stringOrNull(obj, "role"));
	}

	private static String stringOrNull(JsonObject obj, String key) {
		if (!obj.has(key) || obj.get(key).isJsonNull()) {
			return null;
		}
		return obj.get(key).getAsString();
	}
}

package com.github.havardpede.partylink;

import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import java.util.function.Supplier;
import lombok.extern.slf4j.Slf4j;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.WebSocket;
import okhttp3.WebSocketListener;

@Slf4j
class WebSocketManager extends WebSocketListener {
	static final int BASE_BACKOFF_SECONDS = 5;
	static final int MAX_BACKOFF_SECONDS = 60;

	private final OkHttpClient httpClient;
	private final String wsUrl;
	private final Supplier<String> tokenSupplier;
	private final Supplier<String> pairingCodeSupplier;
	private final Consumer<String> onPairResult;
	private final CommandExecutor commandExecutor;
	private final ScheduledExecutorService executor;

	private volatile WebSocket webSocket;
	private volatile boolean authenticated;
	private ScheduledFuture<?> reconnectTask;
	private int backoffSeconds = BASE_BACKOFF_SECONDS;
	private boolean shouldReconnect = true;
	private String pendingRsn;

	WebSocketManager(
			OkHttpClient httpClient,
			String wsUrl,
			Supplier<String> tokenSupplier,
			Supplier<String> pairingCodeSupplier,
			Consumer<String> onPairResult,
			CommandExecutor commandExecutor,
			ScheduledExecutorService executor) {
		this.httpClient = httpClient;
		this.wsUrl = validateWsUrl(wsUrl);
		this.tokenSupplier = tokenSupplier;
		this.pairingCodeSupplier = pairingCodeSupplier;
		this.onPairResult = onPairResult;
		this.commandExecutor = commandExecutor;
		this.executor = executor;
	}

	void connect() {
		if (webSocket != null) {
			return;
		}
		shouldReconnect = true;
		cancelReconnect();
		Request request = new Request.Builder().url(wsUrl).build();
		webSocket = httpClient.newWebSocket(request, this);
		log.info("WebSocket connecting to {}", wsUrl);
	}

	void disconnect() {
		shouldReconnect = false;
		cancelReconnect();
		closeExisting();
		authenticated = false;
		pendingRsn = null;
		log.info("WebSocket disconnected");
	}

	void sendIdentify(String rsn) {
		if (authenticated && webSocket != null) {
			doSendIdentify(rsn);
		} else {
			pendingRsn = rsn;
		}
	}

	void sendPartyState(String state, String passphrase) {
		if (!authenticated || webSocket == null) {
			return;
		}
		JsonObject msg = new JsonObject();
		msg.addProperty("type", "PARTY_STATE");
		msg.addProperty("state", state);
		if (passphrase != null) {
			msg.addProperty("passphrase", passphrase);
		}
		send(msg);
	}

	int getBackoffSeconds() {
		return backoffSeconds;
	}

	@Override
	public void onOpen(WebSocket ws, Response response) {
		log.info("WebSocket opened");
		webSocket = ws;
		String pairingCode = pairingCodeSupplier.get();
		if (pairingCode != null && !pairingCode.isEmpty()) {
			JsonObject pair = new JsonObject();
			pair.addProperty("type", "PAIR");
			pair.addProperty("code", pairingCode);
			send(pair);
		} else {
			JsonObject auth = new JsonObject();
			auth.addProperty("type", "AUTH");
			auth.addProperty("token", tokenSupplier.get());
			send(auth);
		}
	}

	@Override
	public void onMessage(WebSocket ws, String text) {
		JsonObject msg = new JsonParser().parse(text).getAsJsonObject();
		String type = msg.has("type") ? msg.get("type").getAsString() : "";

		switch (type) {
			case "AUTH_OK":
				handleAuthOk();
				break;
			case "AUTH_ERROR":
				handleAuthError(msg);
				break;
			case "PAIR_OK":
				handlePairOk(msg);
				break;
			case "PAIR_ERROR":
				handlePairError(msg);
				break;
			case "COMMAND":
				handleCommand(text);
				break;
			case "ERROR":
				handleError(msg);
				break;
			default:
				log.warn("Unknown WebSocket message type: {}", type);
				break;
		}
	}

	@Override
	public void onFailure(WebSocket ws, Throwable t, Response response) {
		log.warn("WebSocket failure: {}", t.getMessage());
		if (ws != webSocket) {
			return;
		}
		webSocket = null;
		authenticated = false;
		scheduleReconnect();
	}

	@Override
	public void onClosed(WebSocket ws, int code, String reason) {
		log.info("WebSocket closed: {} {}", code, reason);
		if (ws != webSocket) {
			return;
		}
		webSocket = null;
		authenticated = false;
		scheduleReconnect();
	}

	private void handleAuthOk() {
		log.info("WebSocket authenticated");
		authenticated = true;
		backoffSeconds = BASE_BACKOFF_SECONDS;
		if (pendingRsn != null) {
			doSendIdentify(pendingRsn);
			pendingRsn = null;
		}
	}

	private void handleAuthError(JsonObject msg) {
		String reason = msg.has("reason") ? msg.get("reason").getAsString() : "unknown";
		log.error("WebSocket auth failed: {}", reason);
		shouldReconnect = false;
		closeExisting();
	}

	private void handlePairOk(JsonObject msg) {
		String token = msg.has("token") ? msg.get("token").getAsString() : null;
		log.info("WebSocket pairing succeeded");
		onPairResult.accept(token);
		handleAuthOk();
	}

	private void handlePairError(JsonObject msg) {
		String reason = msg.has("reason") ? msg.get("reason").getAsString() : "unknown";
		log.error("WebSocket pairing failed: {}", reason);
		onPairResult.accept(null);
		shouldReconnect = false;
		closeExisting();
	}

	private void handleCommand(String json) {
		Command command = Command.fromJson(json);
		try {
			commandExecutor.execute(command, () -> sendAck(command.id));
		} catch (RuntimeException e) {
			log.error(
					"Failed to execute command {} (type={}): {}",
					command.id,
					command.type,
					e.getMessage());
		}
	}

	private void handleError(JsonObject msg) {
		String message = msg.has("message") ? msg.get("message").getAsString() : "unknown";
		log.warn("Server error: {}", message);
	}

	private void sendAck(String commandId) {
		JsonObject ack = new JsonObject();
		ack.addProperty("type", "ACK");
		ack.addProperty("commandId", commandId);
		send(ack);
	}

	private void doSendIdentify(String rsn) {
		JsonObject identify = new JsonObject();
		identify.addProperty("type", "IDENTIFY");
		identify.addProperty("rsn", rsn);
		send(identify);
	}

	private void send(JsonObject message) {
		WebSocket ws = webSocket;
		if (ws != null) {
			ws.send(message.toString());
		}
	}

	private void scheduleReconnect() {
		if (!shouldReconnect) {
			return;
		}
		log.info("Reconnecting in {}s", backoffSeconds);
		reconnectTask = executor.schedule(this::connect, backoffSeconds, TimeUnit.SECONDS);
		backoffSeconds = Math.min(backoffSeconds * 2, MAX_BACKOFF_SECONDS);
	}

	private void cancelReconnect() {
		if (reconnectTask != null) {
			reconnectTask.cancel(false);
			reconnectTask = null;
		}
	}

	private void closeExisting() {
		WebSocket ws = webSocket;
		if (ws != null) {
			ws.close(1000, "Client disconnect");
			webSocket = null;
		}
	}

	private static String validateWsUrl(String url) {
		if (url == null || url.isEmpty()) {
			throw new IllegalArgumentException("WebSocket URL must not be empty");
		}
		if (!url.startsWith("wss://") && !url.startsWith("ws://")) {
			throw new IllegalArgumentException("WebSocket URL must use ws or wss: " + url);
		}
		return url;
	}
}

